WITH with_windows AS (SELECT id, order_id, quantity, unit_price, LAG(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_quantity, LEAD(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id) AS next_quantity, LEAD(unit_price) OVER (PARTITION BY product_id ORDER BY quantity, id) AS next_unit_price, LAG(unit_price) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_unit_price, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity, id) AS seq_no, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY order_id), 4) AS unit_price_share FROM order_items) SELECT id, order_id, quantity, unit_price, next_quantity, next_unit_price, unit_price_share FROM with_windows ORDER BY order_id
